"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["50940"],{35874(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.no_exigencia.chave_distincao_invalida","status":422,"titulo":"chaveDistincao fora do cat\xe1logo fechado"},"descricao":{"codigo":"uniplus.selecao.no_exigencia.chave_distincao_invalida","requisitos":["UNI-REQ-0068"],"oQueAconteceu":["O campo `chaveDistincao` de um n\xf3 folha n\xe3o corresponde a nenhum dos tr\xeas\\nvalores do cat\xe1logo fechado: `COMPETENCIA_MENSAL`, `EXERCICIO_ANUAL` ou\\n`OCORRENCIA`. A chave qualifica **como** as apresenta\xe7\xf5es distintas de\\numa exig\xeancia se distinguem entre si \u2014 calend\xe1rio deriv\xe1vel (as duas\\nprimeiras) ou uma lista de ocorr\xeancias congeladas (a terceira). Omitir o\\ncampo \xe9 v\xe1lido \u2014 significa contagem bruta de apresenta\xe7\xf5es, sem\\nqualifica\xe7\xe3o nenhuma.","O c\xf3digo de dom\xednio para essa recusa existe (`!Enum.IsDefined` dentro de\\n`CriarFolha`, logo depois de\\n[`quantidade_minima_de_folha_invalida`](/erros/uniplus.selecao.no_exigencia.quantidade_minima_de_folha_invalida)) \u2014\\nmas **nenhum caminho real chega a execut\xe1-lo hoje**, por isso a entrada\\n\xe9 rascunho, n\xe3o publicada.","No `PUT` de documentos exigidos, um valor de `chaveDistincao` fora do cat\xe1logo recebe `uniplus.validacao`. Na leitura da vers\xe3o publicada, um c\xf3digo n\xe3o reconhecido recebe `envelope_codec.envelope_malformado`.","Esta entrada existe para que o c\xf3digo de dom\xednio, j\xe1 registrado no\\ncat\xe1logo, tenha uma p\xe1gina assim que algum dos dois caminhos for\\ndestravado \u2014 por exemplo, se a regra de valida\xe7\xe3o de corpo do pedido for\\nremovida em favor do guard de dom\xednio j\xe1 existente, mesmo trabalho da\\nADR-0125, rastreada em `uniplus-api#1227`."],"comoResolver":["Informe `chaveDistincao` como um dos tr\xeas valores do cat\xe1logo \u2014\\n`COMPETENCIA_MENSAL`, `EXERCICIO_ANUAL` ou `OCORRENCIA` \u2014 ou omita o\\ncampo se a exig\xeancia n\xe3o precisa distinguir apresenta\xe7\xf5es por um padr\xe3o\\nespec\xedfico. Hoje, um valor fora do cat\xe1logo responde com\\n`uniplus.validacao`, n\xe3o com este c\xf3digo \u2014 mas a corre\xe7\xe3o \xe9 a mesma."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"No exigencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);